<script setup>
import {computed} from 'vue';
import MessageText from './MessageText.vue';
import ProductImage from './ProductImage.vue';
import UiIcon from './UiIcon.vue';
import {money,date,observed} from './reportFormat';
const props=defineProps({message:Object,disabled:Boolean});const emit=defineEmits(['action','followup']);
const turn=computed(()=>props.message.data?.version===2?props.message.data:null);
function compareProduct(p){const other=turn.value.state?.pair_ids?.find(id=>id!==p.id)||turn.value.products.find(item=>item.id!==p.id)?.id;emit('action',{type:'compare',product_ids:[p.id,other].filter(Boolean)})}
</script>
<template>
<div v-if="turn" class="advisor-answer"><div class="answer-caption"><span>{{turn.title}}</span><small>{{turn.context_snapshot.category}} · 预算 {{money(turn.context_snapshot.budget)}} · {{turn.context_snapshot.scenario}}</small></div><MessageText v-if="turn.mode==='model'" :text="message.text"/><template v-else><h3 class="answer-lead">{{turn.lead}}</h3><p v-for="(p,i) in turn.paragraphs" :key="i" class="answer-paragraph">{{p}}</p></template>
 <div v-if="turn.facts.length" class="answer-facts"><article v-for="(f,i) in turn.facts" :key="i" :class="{unknown:!f.known}"><small>{{f.title}} · {{f.known?'有资料依据':'待确认'}}</small><b>{{f.value}}</b><p>{{f.explanation}}</p><span v-if="f.source_id">[{{f.source_id}}]</span></article></div>
 <div v-if="turn.comparison_rows.length" class="answer-table-wrap"><table><thead><tr><th>重点</th><th>{{turn.products[0]?.name}}</th><th>{{turn.products[1]?.name}}</th></tr></thead><tbody><tr v-for="r in turn.comparison_rows" :key="r.label"><th>{{r.label}}</th><td v-for="(v,i) in r.values" :key="i">{{v}}</td></tr></tbody></table></div>
 <div v-if="turn.products.length" class="advisor-products"><article v-for="p in turn.products" :key="p.id" :class="['advisor-product',!p.recommendation_eligible&&'reference-product']"><div class="advisor-product-head"><ProductImage :product="p"/><div><span class="advisor-product-badge">{{p.role==='candidate'&&p.recommendation_eligible?'预算内候选':'当前查阅对象'}}</span><small>{{p.brand}} · {{p.subcategory}}</small><h4>{{p.name}}</h4><b>{{money(p.price)}}</b></div></div><p class="advisor-budget-state">{{p.budget_status}}</p><p class="advisor-quote-note">{{p.quote_notice}}</p><template v-if="p.offer"><small class="advisor-variant">{{p.offer.variant}}</small><div class="advisor-price-proof"><span>{{p.offer.platform}} · {{date(p.offer.observed_at)}} 采集</span><a :href="p.offer.source_url" target="_blank" rel="noopener noreferrer">[{{p.source_id}}] 报价原文 ↗</a></div></template><div class="advisor-product-actions"><button :disabled="disabled" @click="emit('action',{type:'quote',product:p})">报价与资料</button><button :disabled="disabled" @click="compareProduct(p)">加入对比</button><button :disabled="disabled" @click="emit('action',{type:'report',product_id:p.id,compare_id:turn.state.pair_ids.find(id=>id!==p.id)})">生成报告 ↗</button></div></article></div>
 <p v-if="turn.follow_up" class="advisor-followup">{{turn.follow_up}}</p><div v-if="turn.actions.length" class="advisor-turn-actions"><button v-for="(a,i) in turn.actions" :key="i" :class="{confirm:a.type==='confirm_profile'}" :disabled="disabled" @click="emit('action',a)"><UiIcon :name="a.type==='compare'?'compare':a.type==='report'?'report':'check'" :size="14"/>{{a.label}}</button></div>
 <details v-if="turn.sources.length" class="advisor-sources"><summary>{{turn.sources.length}} 条资料依据 · 来源与采集日期</summary><ul><li v-for="s in turn.sources" :key="s.id"><a :href="s.url" target="_blank" rel="noopener noreferrer">[{{s.id}}] {{s.label}} ↗</a><span>{{s.type}}<template v-if="s.observed_at"> · {{observed(s.observed_at)}}</template></span></li></ul><p>报价是采集时的记录，具体配置、库存及最终支付金额请在购买页面核对。</p></details>
</div><MessageText v-else :text="message.text"/>
</template>
<style scoped>
.advisor-answer{color:#71627f}.answer-caption{display:flex;gap:12px;align-items:center;justify-content:space-between;margin:0 0 12px;flex-wrap:wrap}.answer-caption>span{font-size:9px;color:#9174b6;background:#f4eefb;border-radius:5px;padding:4px 7px}.answer-caption small{font-size:9px;color:#ad9cb7}.answer-lead{font-size:14px;line-height:1.9;color:#655273;margin:4px 0 14px;font-weight:600}.answer-paragraph{font-size:12px;line-height:1.95;color:#8c779b;margin:8px 0;white-space:pre-wrap;overflow-wrap:anywhere}.answer-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:15px 0}.answer-facts article{padding:14px 16px;border:1px solid #ece2f5;background:#faf7fd;border-radius:9px;min-width:0}.answer-facts article.unknown{background:#fffaf2;border-color:#f1e5d1}.answer-facts small{font-size:9px;color:#aa94ba}.answer-facts b{font-size:12px;display:block;line-height:1.8;margin:8px 0;color:#84609e}.answer-facts p{font-size:10px;color:#a18bab;line-height:1.9;margin:0}.answer-facts span{font-size:8px;color:#b09bbd}.answer-table-wrap{overflow:auto;border:1px solid #ede3f4;border-radius:9px;margin:17px 0}.answer-table-wrap table{border-collapse:collapse;width:100%;table-layout:fixed}.answer-table-wrap th,.answer-table-wrap td{padding:12px 11px;font-size:10px;line-height:1.8;text-align:left;min-width:0;border-bottom:1px solid #eee7f5;overflow-wrap:anywhere}.answer-table-wrap thead th{font-weight:400;background:#faf6fd;color:#a18bae}.answer-table-wrap th:first-child{width:90px;color:#9a82a8;font-weight:400}.answer-table-wrap td{color:#8b759a}.advisor-products{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:17px 0}.advisor-product{border:1px solid #e9ddf2;background:#fff;border-radius:12px;padding:17px;min-width:0}.advisor-product-head{display:flex;gap:12px;align-items:center}.advisor-product-head>.product-photo{width:75px;height:84px;flex-shrink:0;background:#faf7fe}.advisor-product-head>div{min-width:0}.advisor-product-head small{display:block;color:#b09cbd;font-size:8px;line-height:1.8;margin-top:5px}.advisor-product-badge{font-size:8px;display:inline-block;border-radius:4px;background:#eef7f2;color:#739e8d;padding:4px 6px}.reference-product .advisor-product-badge{background:#fbf1e5;color:#b89a71}.advisor-product-head h4{font-size:13px;line-height:1.7;color:#725880;margin:5px 0}.advisor-product-head b{font-size:18px;color:#9c70be}.advisor-budget-state{font-size:10px;color:#9a80aa;margin:13px 0 7px;line-height:1.8}.advisor-quote-note{font-size:9px;color:#b09bb9;line-height:1.8;margin:0 0 9px}.advisor-variant{font-size:9px;color:#a48db1;line-height:1.8;display:block;overflow-wrap:anywhere}.advisor-price-proof{display:flex;gap:7px;justify-content:space-between;flex-wrap:wrap;font-size:8px;margin-top:9px;color:#b19bbc}.advisor-price-proof a{color:#a382bd}.advisor-product-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:14px;padding-top:12px;border-top:1px solid #f0e9f6}.advisor-product-actions button{border:0;background:none;font-size:9px;color:#a278b8;padding:0}.advisor-followup{font-size:12px;line-height:1.9;color:#9272a7;margin:17px 0 10px}.advisor-turn-actions{display:flex;gap:9px;flex-wrap:wrap;margin:12px 0}.advisor-turn-actions button{display:flex;gap:6px;align-items:center;padding:9px 12px;border-radius:7px;background:#faf5fe;color:#a180b9;border:1px solid #eadcf4;font-size:10px}.advisor-turn-actions button.confirm{background:#a17bc0;border-color:#a17bc0;color:#fff}.advisor-sources{border-top:1px solid #f0e8f6;margin-top:17px;padding-top:12px;font-size:9px;color:#ac96b8}.advisor-sources summary{cursor:pointer;color:#a389b6}.advisor-sources ul{padding-left:15px}.advisor-sources li{margin:10px 0;line-height:1.8}.advisor-sources li>span{display:block;font-size:8px;color:#b3a0bd}.advisor-sources p{font-size:8px;line-height:1.8}.advisor-sources a{font-size:9px;color:#9f80b3}.advisor-answer :deep(.message-text){color:#897297}
.answer-paragraph,.answer-facts p,.advisor-variant{color:#897297}.advisor-product-head b{color:#9465b3}.advisor-quote-note{color:#9b85a7}.advisor-product-actions button{font-size:10px;color:#9674a8}@media(max-width:1250px){.advisor-products{grid-template-columns:1fr}.advisor-product-head>.product-photo{width:65px;height:70px}}@media(max-width:720px){.answer-facts{grid-template-columns:1fr}.answer-caption small{font-size:8px}.answer-lead{font-size:12px}.answer-paragraph{font-size:11px}.answer-table-wrap th:first-child{width:65px}.answer-table-wrap th,.answer-table-wrap td{font-size:9px;padding:9px 7px}.advisor-product{padding:14px}.advisor-product-head h4{font-size:12px}}
</style>
